from typing import List, Optional

def changes_count(coloring: List[bool], n: int) -> int:
    return sum(1 for i in range(n) if coloring[i] != coloring[i + 1])

def sperner_parity_holds(coloring: List[bool], n: int) -> bool:
    return (changes_count(coloring, n) % 2 == 1) == (coloring[0] != coloring[n])

def first_change(coloring: List[bool], n: int) -> Optional[int]:
    return next((i for i in range(n) if coloring[i] != coloring[i+1]), None)

for c in [[True,True,False,True,False],[True,False,False,False,True],[False,True,True,True,True]]:
    n = len(c) - 1
    print(c, "changes=", changes_count(c, n), "parity-theorem:", sperner_parity_holds(c, n),
          "witness:", first_change(c, n) if c[0] != c[n] else None)

def affine_fp(a, b): return b/(1-a)
def iterate(a, b, x0, n):
    x = x0
    for _ in range(n): x = a*x + b
    return x
def bound(a, b, x0, n): return abs(a)**n * abs(x0 - affine_fp(a,b))

for a,b,x0 in [(0.5,3.0,0.0),(-0.8,1.0,10.0),(0.9,-2.0,5.0)]:
    xs = affine_fp(a,b)
    print(f"f={a}x+{b}  x*={xs:.4f}")
    for n in (1,5,10,25,50):
        xn = iterate(a,b,x0,n); err = abs(xn-xs)
        print(f"  n={n:>3} x_n={xn:>12.7f} err={err:.3e} bound={bound(a,b,x0,n):.3e}")

def affine_fp(a, b): return b/(1-a)
def preserves(a, b, lo, hi):
    assert 0 <= a < 1
    return (a*lo+b >= lo-1e-15) and (a*hi+b <= hi+1e-15)

for a,b,lo,hi in [(0.5,2.0,0.0,10.0),(0.25,3.0,1.0,5.0),(0.9,0.5,0.0,6.0)]:
    xs = affine_fp(a,b); p = preserves(a,b,lo,hi)
    print(f"f={a}x+{b} on [{lo},{hi}] preserves={p} x*={xs:.3f} inside={lo<=xs<=hi}")

