function LOCATE_CHANGE(c[0..n]):
    if c[0] == c[n]:
        return first i with c[i] != c[i+1], or NONE   # parity forces nothing
    for i in 0 .. n-1:
        if c[i] != c[i+1]:
            return i                                   # guaranteed by odd parity
    error "unreachable: sperner_parity forces a change"

