function AFFINE_PICARD(a, b, x0, eps):
    require |a| < 1 and eps > 0
    xstar <- b / (1 - a)
    d0 <- |x0 - xstar|
    if d0 <= eps: return (x0, 0)
    n* <- ceil( log(eps / d0) / log(|a|) )
    x <- x0
    repeat n* times: x <- a*x + b
    return (x, n*)
